    case 12:
      if (lookahead == 'l') ADVANCE(23);
      END_STATE();
    case 13:
      ACCEPT_TOKEN(anon_sym_ge);
      END_STATE();
    case 14:
      ACCEPT_TOKEN(anon_sym_gt);
      END_STATE();
    case 15:
